from functools import cache, cached_property, reduce, total_ordering, wraps

@cache
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
print(fib(50), fib.cache_info().hits > 0)

def shout(f):
    @wraps(f)
    def inner(*a, **k):
        return f(*a, **k).upper()
    return inner

@shout
def hi(name):
    return f'hi {name}'
print(hi('ann'), hi.__name__)

